export function audioTimingLabels(language='EN'){
 const i=Math.max(0,['EN','HU','DE','FR','ES','IT','PT','PL'].indexOf(language));
 const words={
 title:'Sound and picture alignment|Hang és kép összeigazítása|Ton und Bild ausrichten|Aligner son et image|Alinear sonido e imagen|Allinea suono e immagine|Alinhar som e imagem|Wyrównanie dźwięku i obrazu',
 load:'Load sound waveform|Hanghullám betöltése|Ton-Wellenform laden|Charger la forme d’onde|Cargar forma de onda|Carica forma d’onda|Carregar forma de onda|Wczytaj przebieg dźwięku',
 cue:'Sound cue (source seconds)|Hangjelölő (forrás másodperc)|Tonmarke (Quellsekunden)|Repère sonore (secondes source)|Marca sonora (segundos fuente)|Punto audio (secondi sorgente)|Marca sonora (segundos da fonte)|Punkt dźwięku (sekundy źródła)',
 previous:'−1 frame|−1 képkocka|−1 Bild|−1 image|−1 fotograma|−1 fotogramma|−1 fotograma|−1 klatka',next:'+1 frame|+1 képkocka|+1 Bild|+1 image|+1 fotograma|+1 fotogramma|+1 fotograma|+1 klatka',
 rate:'Alignment FPS — match your video|Igazítási FPS — egyezzen a videóddal|Ausrichtungs-FPS wie Video|FPS d’alignement comme la vidéo|FPS de alineación como el vídeo|FPS allineamento come video|FPS de alinhamento como vídeo|FPS wyrównania jak w filmie',
 help:'Click the waveform to mark a sound event; arrow keys move one frame. This is source audio, before gain and fades. Preview the final mix in Video workshop.|Kattints a hullámra egy hangesemény jelöléséhez; a nyílbillentyű egy képkockát lép. Ez a forráshang, hangerő és lekeverés előtt. A végső keverést a Videóműhely rövid előnézetében hallgasd meg.|Welle anklicken, Pfeiltasten bewegen ein Bild. Quellton vor Pegel/Blenden. Endmix in Videovorschau prüfen.|Cliquez pour marquer un son ; flèches pour une image. Son source avant volume/fondus. Vérifiez le mix dans l’aperçu vidéo.|Haz clic para marcar; flechas avanzan un fotograma. Audio fuente antes de volumen/fundidos. Comprueba mezcla en vista previa.|Clicca per segnare; frecce per un fotogramma. Audio sorgente prima di volume/dissolvenze. Verifica mix nell’anteprima video.|Clique para marcar; setas movem um fotograma. Áudio fonte antes de volume/fades. Confira mistura na prévia do vídeo.|Kliknij, by zaznaczyć; strzałki przesuwają o klatkę. Źródło przed głośnością/zanikami. Sprawdź miks w podglądzie filmu.',
 picture:'Show picture at timeline time|Kép mutatása az idővonal idején|Bild zur Timeline-Zeit zeigen|Afficher l’image au temps du montage|Mostrar imagen en tiempo de montaje|Mostra immagine al tempo del montaggio|Mostrar imagem no tempo da montagem|Pokaż obraz w czasie montażu',
 time:'Picture time on timeline (s)|Kép ideje az idővonalon (s)|Bildzeit in Timeline (s)|Temps image au montage (s)|Tiempo de imagen en montaje (s)|Tempo immagine nel montaggio (s)|Tempo da imagem na montagem (s)|Czas obrazu na osi (s)',
 align:'Align sound cue to this picture|Hangjelölő igazítása ehhez a képhez|Tonmarke an dieses Bild setzen|Aligner le repère sonore sur cette image|Alinear marca sonora con esta imagen|Allinea punto audio a questa immagine|Alinhar marca sonora a esta imagem|Wyrównaj punkt dźwięku do obrazu',
 earlier:'Sound −1 frame|Hang −1 képkocka|Ton −1 Bild|Son −1 image|Sonido −1 fotograma|Suono −1 fotogramma|Som −1 fotograma|Dźwięk −1 klatka',later:'Sound +1 frame|Hang +1 képkocka|Ton +1 Bild|Son +1 image|Sonido +1 fotograma|Suono +1 fotogramma|Som +1 fotograma|Dźwięk +1 klatka',
 arrangement:'Start-time fine adjustment|Kezdési idő finomítása|Startzeit fein einstellen|Ajuster le début|Ajustar inicio|Regola inizio|Ajustar início|Dostosuj początek',
 videoHelp:'Choose a sound cue and a picture time, then align. Only the sound start changes; Undo is available. Looping uses the first occurrence. The picture is a paused source preview, not the mixed export; render a short preview to check sync. Waveform analysis is local and uses no AI or GPU.|Válassz hangjelölőt és képidőt, majd igazítsd össze. Csak a hang kezdete változik; visszavonható. Ismétlésnél az első előfordulást igazítja. A kép megállított forrás-előnézet, nem a kevert export; rövid előnézettel ellenőrizd a szinkront. A hullámelemzés helyi, MI és GPU nélkül.|Tonmarke und Bildzeit wählen, dann ausrichten. Nur Tonstart ändert sich; rückgängig möglich. Bei Schleifen erste Wiederholung. Standbild ist Quellvorschau, kein Mix; kurze Vorschau prüfen. Lokale Analyse ohne KI/GPU.|Choisissez repère et temps image, puis alignez. Seul le début sonore change ; annulable. Boucle : première occurrence. Image source figée, pas le mix ; vérifiez un aperçu court. Analyse locale sans IA/GPU.|Elige marca y tiempo de imagen, luego alinea. Solo cambia inicio del audio; deshacer disponible. Bucle: primera repetición. Imagen fuente pausada, no mezcla; comprueba vista corta. Análisis local sin IA/GPU.|Scegli punto audio e tempo immagine, poi allinea. Cambia solo inizio audio; annullabile. Loop: prima occorrenza. Immagine sorgente ferma, non mix; verifica anteprima breve. Analisi locale senza IA/GPU.|Escolha marca e tempo da imagem, depois alinhe. Só muda início do som; pode desfazer. Loop: primeira ocorrência. Imagem fonte parada, não mistura; confira prévia curta. Análise local sem IA/GPU.|Wybierz punkt dźwięku i czas obrazu, potem wyrównaj. Zmienia się tylko początek dźwięku; można cofnąć. Pętla: pierwsze wystąpienie. Obraz to zatrzymany podgląd źródła, nie miks; sprawdź krótki podgląd. Analiza lokalna bez AI/GPU.',
 negative:'The sound would have to start before the video. Choose a later picture or an earlier sound cue, or trim the sound first.|A hangnak a videó előtt kellene kezdődnie. Válassz későbbi képet vagy korábbi hangjelölőt, vagy előbb vágd meg a hangot.|Ton müsste vor Video beginnen. Späteres Bild, frühere Tonmarke oder Ton trimmen.|Le son commencerait avant la vidéo. Choisissez une image plus tardive, un repère antérieur ou coupez le son.|El sonido empezaría antes del vídeo. Elige imagen posterior, marca anterior o recorta audio.|Il suono inizierebbe prima del video. Scegli immagine successiva, punto precedente o taglia audio.|O som começaria antes do vídeo. Escolha imagem posterior, marca anterior ou corte o áudio.|Dźwięk zaczynałby się przed filmem. Wybierz późniejszy obraz, wcześniejszy punkt lub przytnij dźwięk.',
 cancelWave:'Cancel waveform analysis|Hullámelemzés megszakítása|Wellenanalyse abbrechen|Annuler analyse sonore|Cancelar análisis de onda|Annulla analisi audio|Cancelar análise de onda|Anuluj analizę dźwięku',
 loading:'Analysing locally…|Helyi elemzés…|Lokale Analyse…|Analyse locale…|Análisis local…|Analisi locale…|Análise local…|Analiza lokalna…',
 failed:'Waveform unavailable. You can still use playback and the time fields.|A hullámkép nem érhető el. A lejátszó és az időmezők továbbra is használhatók.|Wellenform nicht verfügbar. Wiedergabe und Zeitfelder bleiben nutzbar.|Forme d’onde indisponible. Lecture et champs de temps restent utilisables.|Forma de onda no disponible. Puedes usar reproducción y tiempos.|Forma d’onda non disponibile. Riproduzione e tempi restano disponibili.|Forma de onda indisponível. Reprodução e tempos continuam disponíveis.|Przebieg niedostępny. Odtwarzanie i pola czasu nadal działają.',
 silent:'No audible signal in this range|Ebben a tartományban nincs hallható jel|Kein Tonsignal im Bereich|Aucun signal sonore dans cet intervalle|Sin señal audible en este tramo|Nessun segnale udibile nell’intervallo|Sem sinal audível neste intervalo|Brak sygnału w tym zakresie',
 start:'Sound starts at|Hang kezdete|Ton beginnt bei|Début du son|Inicio del sonido|Inizio del suono|Início do som|Początek dźwięku'};
 return Object.fromEntries(Object.entries(words).map(([k,v])=>[k,v.split('|')[i]]));
}

export const audioTimingCss=`.at-panel[hidden],.at-panel [hidden]{display:none!important}.at-panel{padding:14px;margin:12px 0;border:1px solid #506878;border-radius:12px;background:#132a36;min-width:0}.at-panel canvas{display:block;width:100%;height:150px;background:#081721;border-radius:8px;touch-action:none;cursor:crosshair}.at-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:8px 0}.at-panel label{display:block;min-width:0}.at-panel input,.at-panel select{max-width:100%}.at-help{font-size:15px;line-height:1.6;color:#bfced6}.at-status{min-height:1.5em;font-size:16px;overflow-wrap:anywhere}.at-panel audio{width:100%}.at-panel button{min-height:43px}.at-panel canvas:focus-visible{outline:3px solid #6ddbe2}.at-cue{width:150px}.at-time{width:180px}`;

export function audioWavePanel({host,language,coreFactory,labels,fetchWave,audio,getFps=()=>24,onCue=()=>{},isBusy=()=>false,onAnalysis=()=>{}}){
 const C=coreFactory(),t=labels(language),D=document,el=(tag,text='')=>{const n=D.createElement(tag);n.textContent=text;return n;};let source=null,key='',data=null,cue=0,request=null,version=0;const cache=new Map(),box=el('section'),row=el('div'),load=el('button',t.load),canvas=el('canvas'),status=el('p'),label=el('label',t.cue),value=el('input'),steps=el('div'),prev=el('button',t.previous),next=el('button',t.next);
 box.className='at-panel';row.className=steps.className='at-row';status.className='at-status';status.setAttribute('role','status');load.type=prev.type=next.type='button';load.dataset.atAction='loadWave';prev.dataset.atAction='cuePrevious';next.dataset.atAction='cueNext';canvas.width=1024;canvas.height=150;canvas.tabIndex=0;canvas.setAttribute('role','slider');canvas.setAttribute('aria-label',t.cue);canvas.dataset.atField='wave';canvas.hidden=true;value.type='number';value.className='at-cue';value.dataset.atField='cue';label.append(value);row.append(load);steps.append(label,prev,next);box.append(row,canvas,steps,status);const help=el('p',t.help);help.className='at-help';box.append(help);host.append(box);box.hidden=true;
 function draw(){if(!source)return;value.min=String(source.in);value.max=String(source.out);value.step=String(1/C.fps(getFps()));value.value=cue.toFixed(6);prev.disabled=next.disabled=isBusy()||cue<=source.in&&cue>=source.out;prev.disabled=isBusy()||cue<=source.in;next.disabled=isBusy()||cue>=source.out;load.disabled=isBusy()&&!request;load.textContent=request?t.cancelWave:t.load;canvas.hidden=!data;if(!data)return;const x=canvas.getContext('2d');x.clearRect(0,0,1024,150);x.fillStyle='#65ccc4';data.peaks.forEach((p,i)=>x.fillRect(i,75-p*68,1,Math.max(1,p*136)));x.fillStyle='#ffc780';x.fillRect(C.clamp((cue-source.in)/(source.out-source.in),0,1)*1022,0,2,150);canvas.setAttribute('aria-valuemin',String(source.in));canvas.setAttribute('aria-valuemax',String(source.out));canvas.setAttribute('aria-valuenow',String(cue));canvas.setAttribute('aria-valuetext',cue.toFixed(3)+' s');}
 function mark(time,seek=true){if(!source||isBusy())return;cue=C.clamp(time,source.in,source.out);if(seek){audio.pause();try{audio.currentTime=cue;}catch{}}draw();onCue(cue);}
 function select(s){const nextKey=s?JSON.stringify([s.key,s.in,s.out]):'';if(key===nextKey){source=s;draw();return;}version++;if(request){request.abort();request=null;onAnalysis(null);}source=s;key=nextKey;box.hidden=!s;data=cache.get(key)||null;status.textContent='';if(!s){audio.pause();return;}cue=s.in;draw();onCue(cue);}
 async function loadWave(){if(!source||request||isBusy())return;const own=++version,s={...source},k=key,abort=new AbortController();request=abort;onAnalysis(abort);status.textContent=t.loading;draw();try{const result=C.wave(await fetchWave(s,abort.signal));if(own!==version)return;data=result;cache.set(k,result);if(cache.size>8)cache.delete(cache.keys().next().value);status.textContent=result.silent?t.silent:'';}catch(e){if(own===version)status.textContent=e.name==='AbortError'?'':t.failed;}finally{if(own===version){request=null;onAnalysis(null);draw();}}}
 load.addEventListener('click',()=>{if(request)request.abort();else void loadWave();});value.addEventListener('change',()=>mark(Number(value.value)));prev.addEventListener('click',()=>mark(C.step(cue,-1,getFps(),source.in,source.out)));next.addEventListener('click',()=>mark(C.step(cue,1,getFps(),source.in,source.out)));canvas.addEventListener('click',e=>{if(!data||!source)return;const r=canvas.getBoundingClientRect();mark(source.in+C.clamp((e.clientX-r.left)/r.width,0,1)*(source.out-source.in));});canvas.addEventListener('keydown',e=>{if(!source||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();mark(e.key==='Home'?source.in:e.key==='End'?source.out:C.step(cue,e.key==='ArrowLeft'?-1:1,getFps(),source.in,source.out));});audio.addEventListener('timeupdate',()=>{if(!source)return;if(audio.currentTime>=source.out){audio.pause();mark(source.out,false);}else mark(audio.currentTime,false);});audio.addEventListener('loadedmetadata',()=>{if(source)try{audio.currentTime=cue;}catch{}});window.addEventListener('pagehide',()=>{version++;request?.abort();audio.pause();});
 return {select,load:loadWave,getCue:()=>cue,mark,refresh:draw,box};
}

export function videoAudioAlignmentPanel({host,language,coreFactory,labels,waveFactory,getProject,getSelected,commit,isBusy,fetchWave,previewAt,setActive,onError,onAnalysis=()=>{}}){
 const C=coreFactory(),t=labels(language),D=document,el=(tag,text='')=>{const n=D.createElement(tag);n.textContent=text;return n;};let soundId='',time=0,active=false;const box=el('section'),title=el('h2',t.title),audio=el('audio'),waveHost=el('div'),row=el('div'),label=el('label',t.time),input=el('input'),rate=el('p'),note=el('p'),line=el('p');box.className='at-panel';box.dataset.atPanel='alignment';audio.controls=true;audio.preload='none';row.className='at-row';note.className='at-help';note.textContent=t.videoHelp;input.type='number';input.className='at-time';input.min='0';input.dataset.atField='pictureTime';label.append(input);box.append(title,audio,waveHost,label,row,rate,line,note);host.append(box);
 const selected=()=>{const p=getProject(),s=getSelected();return s?.kind==='sound'?p.sounds.find(a=>a.id===s.id):null;},fps=()=>{const p=getProject();return C.fps(p.output.fps||p.assets.find(a=>a.id===p.clips[0]?.asset)?.fps||24);},duration=()=>getProject().clips.reduce((n,c)=>n+(c.out-c.in)/c.speed,0);
 const wave=waveFactory({host:waveHost,language,coreFactory,labels,audio,getFps:fps,isBusy,fetchWave,onAnalysis,onCue:updateLine});
 function button(key,fn){const b=el('button',t[key]);b.type='button';b.dataset.atAction=key;b.addEventListener('click',()=>{if(!isBusy())fn();});row.append(b);return b;}
 function updateLine(){const s=selected();line.textContent=s?t.start+' '+s.at.toFixed(6)+' s · '+t.cue+': '+wave.getCue().toFixed(6)+' s':'';}
 function seek(value){if(isBusy()||!selected()||!duration())return;time=C.clamp(value,0,Math.max(0,duration()-1/fps()));active=true;setActive(true);previewAt(time);input.value=time.toFixed(6);updateLine();}
 const picture=button('picture',()=>seek(time)),prev=button('previous',()=>seek(C.step(time,-1,fps(),0,Math.max(0,duration()-1/fps()),true))),next=button('next',()=>seek(C.step(time,1,fps(),0,Math.max(0,duration()-1/fps()),true)));
 function editAt(at){const p=getProject(),s=p.sounds.find(a=>a.id===soundId);if(!s)return;s.at=at;commit(p);}
 const align=button('align',()=>{const s=selected();if(!s)return;try{editAt(C.align(s,wave.getCue(),time));}catch{onError(Error(t.negative));}}),earlier=button('earlier',()=>{const s=selected();if(s)editAt(C.step(s.at,-1,fps()));}),later=button('later',()=>{const s=selected();if(s)editAt(C.step(s.at,1,fps()));});
 input.addEventListener('change',()=>seek(Number(input.value)));
 function refresh(){const p=getProject(),s=selected();box.hidden=!s;if(!s){if(active){active=false;setActive(false);}soundId='';wave.select(null);return;}if(soundId!==s.id){soundId=s.id;active=false;setActive(false);time=C.clamp(s.at,0,duration());const a=p.assets.find(a=>a.id===s.asset);audio.src='/api/video/media?id='+encodeURIComponent(a.id);audio.load();}const a=p.assets.find(a=>a.id===s.asset);wave.select({key:a.hash,in:s.in,out:s.out,project:p,soundId:s.id});wave.refresh();input.value=time.toFixed(6);input.max=String(Math.max(0,duration()-1/fps()));input.step=String(1/fps());input.disabled=isBusy()||!p.clips.length;rate.textContent=fps().toFixed(3)+' fps · '+(1000/fps()).toFixed(3)+' ms';for(const b of [picture,prev,next,align])b.disabled=isBusy()||!p.clips.length;earlier.disabled=isBusy()||s.at<=0;later.disabled=isBusy()||s.at>=1800;updateLine();}
 return {refresh,seek,wave,isActive:()=>active};
}
